// HasRetirement applies the HasEdge predicate on the "retirement" edge.
func HasRetirement() predicate.StorageRetirementEntry {
	return predicate.StorageRetirementEntry(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, RetirementTable, RetirementColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRetirementWith applies the HasEdge predicate on the "retirement" edge with a given conditions (other predicates).
func HasRetirementWith(preds ...predicate.StorageRetirement) predicate.StorageRetirementEntry {
	return predicate.StorageRetirementEntry(func(s *sql.Selector) {
		step := newRetirementStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

