// HasMigrationTask applies the HasEdge predicate on the "migration_task" edge.
func HasMigrationTask() predicate.StorageRetirementEntry {
	return predicate.StorageRetirementEntry(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, MigrationTaskTable, MigrationTaskColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasMigrationTaskWith applies the HasEdge predicate on the "migration_task" edge with a given conditions (other predicates).
func HasMigrationTaskWith(preds ...predicate.StorageTask) predicate.StorageRetirementEntry {
	return predicate.StorageRetirementEntry(func(s *sql.Selector) {
		step := newMigrationTaskStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.StorageRetirementEntry) predicate.StorageRetirementEntry {
	return predicate.StorageRetirementEntry(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.StorageRetirementEntry) predicate.StorageRetirementEntry {
	return predicate.StorageRetirementEntry(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.StorageRetirementEntry) predicate.StorageRetirementEntry {
	return predicate.StorageRetirementEntry(sql.NotPredicates(p))
}
